const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label)=>/^https:\/\//.test(url||'')?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer" style="text-decoration:underline">${esc(label)}</a>`:esc(label);
(async()=>{try{const response=await fetch('/api/catalog');if(!response.ok)throw Error();const {cars}=await response.json();document.getElementById('image-sources').innerHTML=cars.map(car=>{const photos=[{url:car.image,credit:car.imageCredit,source:car.imageSource,license:car.imageLicense,licenseUrl:car.imageLicense==='CC BY 3.0'?'https://creativecommons.org/licenses/by/3.0/':''},...(car.gallery||[])].filter(p=>p.credit);return photos.length?`<section class="account-card" id="${esc(car.id)}"><h2>${esc(car.name)}</h2>${photos.map((p,i)=>`<p>Photo ${i+1}: ${link(p.source,p.credit)} · ${link(p.licenseUrl,p.license||'See source for licence')}. Cropped to fit.</p>`).join('')}</section>`:'';}).join('')||'<p>Car photographs supplied by GoRide.</p>';if(location.hash){const target=document.getElementById(decodeURIComponent(location.hash.slice(1)));target?.scrollIntoView();}}catch{document.getElementById('image-sources').textContent='Image information could not be loaded. Please refresh or contact GoRide.';}})();
